ValidationRule.errorConditionFormula:
AND(
  TEXT(PRIORVALUE(Status)) = "Pre-Offer",

  /* Only validate when the value is actually changing */
  TEXT(Status) <> TEXT(PRIORVALUE(Status)),

  NOT(
    OR(
      /* Always allowed */
      ISPICKVAL(Status, "Withdrawn/Declined"),

      /* Post-Lottery allowed transitions */
      AND(Has_Lottery_Run__c, ISPICKVAL(Status, "Seat Offered")),
      AND(Has_Lottery_Run__c, ISPICKVAL(Status, "Waitlisted")),
      AND(Has_Lottery_Run__c, ISPICKVAL(Status, "Offer Rescinded due to Seat Optimization"))
    )
  )
)
